{
  "policy": {
    "case": "Synthetic delivery appointment desk",
    "organisation": "Nova Teslimat",
    "language": "Turkish",
    "address": "Polite siz forms",
    "sources": [
      {
        "id": "brief",
        "reference": "BRIEF.md",
        "rules": "Organisation, parcel-code request, appointment lookup, weekday appointments, full read-back, confirmation before saving, honest result reporting, no save retry, farewell and hangup."
      },
      {
        "id": "amendment_v2",
        "reference": "BRIEF.md / Later amendment, version 2",
        "rules": "Available appointment times are 09:00–16:00 inclusive."
      },
      {
        "id": "hours_v1",
        "reference": "hours.docx / word/document.xml / Original hours, version 1 / table",
        "rules": "Original start 09:00 and end 17:00. The start survives; the end is superseded."
      },
      {
        "id": "fixture",
        "reference": "customers.xlsx / Synthetic call variables / A1:B2",
        "rules": "The documented synthetic call variables are parcel_code=000317 and now=2026-10-14T11:00."
      },
      {
        "id": "flow",
        "reference": "flow.pdf / attached raster page 1",
        "sequence": [
          "Read current slot",
          "Read back proposal and ask confirmation",
          "Only after yes: save_slot",
          "ok true: confirm saved; ok false: apologise",
          "Say goodbye, then end call"
        ]
      },
      {
        "id": "contract",
        "reference": "openapi.json and DEPLOYED MOCK OPENAPI",
        "rules": "The two contracts agree. Only lookup_slot and save_slot exist. Their success fields are inside the response body."
      },
      {
        "id": "deployment",
        "reference": "DEPLOYMENT",
        "rules": "Use the supplied mock base URL for both service operations."
      },
      {
        "id": "reader",
        "reference": "README.md",
        "rules": "Identifies the supplied policy, spreadsheet, Word table, raster diagram and authoritative service contract."
      }
    ],
    "priority_order": [
      "Deployment determines the service destination; OpenAPI determines operation names, request fields, field types and response shapes.",
      "The explicit later amendment overrides conflicting older policy: 16:00 replaces 17:00.",
      "The remaining BRIEF.md requirements and the raster sequence diagram govern the conversation and save ordering.",
      "The Word table applies only where not superseded.",
      "The spreadsheet supplies synthetic call inputs, not proof of a successful lookup or write.",
      "The example illustrates a Friday 15:00 request and confirmation; platform examples supply syntax only."
    ],
    "overrides": [
      {
        "earlier": "hours.docx: End=17:00",
        "later": "BRIEF.md version 2: End=16:00 inclusive",
        "effective": "09:00 through 16:00 inclusive"
      }
    ],
    "opening": "Merhaba, Nova Teslimat adına yardımcı oluyorum. Gönderi kodunuzu alabilir miyim?",
    "sequence": [
      "Identify Nova Teslimat and ask for the parcel code. Preserve leading zeroes and assemble a code supplied in parts before lookup.",
      "Call lookup_slot with the complete code supplied by the caller. A fixture value alone does not satisfy this step.",
      "Proceed only after an actual response with ok=true and found=true, readable current appointment fields and a usable call now.",
      "Read the current appointment aloud before presenting the change for confirmation.",
      "Collect or offer a weekday date and a time inside the amended window. Retain requested details already supplied by the caller.",
      "Validate the complete proposal before presenting the final read-back.",
      "Read back the parcel code, proposed date and time, and ask for explicit confirmation.",
      "A correction invalidates the preceding confirmation. Preserve unchanged proposal elements, validate again and read back the complete proposal again. A parcel-code correction requires a new lookup.",
      "After a clear confirmation of the current complete read-back, submit save_slot exactly once.",
      "Report the actual save outcome, say goodbye, then perform silent hangup."
    ],
    "calendar": {
      "anchor": "Use the call variable now exclusively. Do not use the machine clock or platform date placeholders.",
      "local_time": "Use the local wall date and time represented by now; the case supplies no timezone conversion rule.",
      "weekdays": "Monday through Friday, computed with weekday() values 0 through 4.",
      "hours": "Compare integer minutes since midnight: 540 <= hour*60+minute <= 960.",
      "holidays": "No holiday calendar or holiday exclusion is supplied. Do not import one; a weekday is not excluded on an assumed holiday.",
      "past_slots": "Offer appointments at or after the call's now. Explain a past proposal and obtain a new proposal rather than silently moving it.",
      "default_offer": "Round now upward to the next whole minute only when generating an offer. If before 09:00, offer 09:00 that day. If after 16:00 or on a weekend, advance to the next Monday–Friday date at 09:00. This never changes a confirmed customer proposal.",
      "date_interpretation": "Accept explicit ISO dates, day.month.year or day/month/year dates, today, tomorrow and a bare weekday, optionally preceded by bu or followed by günü. A bare weekday means its first occurrence on or after the call date. If its time would be past, request clarification rather than advancing a week. Other ambiguous expressions require a concrete date.",
      "time_interpretation": "Normalize an unambiguous spoken time to HH:MM. Numeric HH, HH:MM and HH.MM representations are accepted; an explicit whole hour gets :00. Incomplete or ambiguous speech is collected before validation.",
      "display": "Read dates in Turkish using day.month.year and times as hours and minutes. Send dates as YYYY-MM-DD and times as HH:MM.",
      "capacity": "No inventory or capacity endpoint exists. Offers use the documented weekday and hour window; do not claim an independent capacity reservation.",
      "other_limits": "No booking horizon, minimum notice interval or product-specific deadline is supplied."
    },
    "amounts": {
      "applicable": false,
      "rules": "There are no debts, monetary amounts, amount bands, floors, partial payments or monetary rounding rules."
    },
    "security_and_products": {
      "identity_checks": "None. Do not ask for bank identity information or security answers.",
      "products": [],
      "product_note_rules": [],
      "notes": "No note operation or note policy exists.",
      "transfers": "No transfer endpoint exists.",
      "collection_branches": "Debt disputes, hardship, persuasion, restructuring, promises and collection closing codes do not apply."
    },
    "response_rules": {
      "lookup": "Require actual boolean ok=true and found=true. HTTP success alone is insufficient. Existing appointments outside the new availability window may still be read; the amended window constrains the proposed replacement.",
      "save": "Actual boolean ok=true establishes success. The save response's found field is not an additional success requirement. ok=false is failure, even in an HTTP-success envelope. Missing or malformed ok leaves the outcome unconfirmed.",
      "writes": "One save submission per call, maxRetries=0. Never repeat a failed or uncertain save. Clear stale result flags immediately before submission.",
      "pending_vs_recorded": "A proposal and an explicit confirmation are not a recorded change. Recorded state is set only by a successful save response."
    },
    "closing_combinations": [
      {
        "condition": "save_slot returns ok=true, with any found value or with found absent",
        "action": "Confirm that the change was saved, say goodbye, then hang up."
      },
      {
        "condition": "save_slot returns ok=false, with any found value or with found absent",
        "action": "Apologise, do not claim success, do not retry, say goodbye, then hang up."
      },
      {
        "condition": "Save transport failure, malformed response or missing boolean ok",
        "action": "Apologise and say the saved change cannot be verified; do not retry or claim that it was saved; say goodbye and hang up."
      },
      {
        "condition": "lookup_slot returns ok=true and found=false",
        "action": "Explain that the appointment could not be found; do not save; say goodbye and hang up."
      },
      {
        "condition": "Lookup ok is false, absent or malformed, regardless of found; or found is absent or malformed",
        "action": "Apologise for being unable to retrieve the appointment; do not save; say goodbye and hang up."
      },
      {
        "condition": "Unreadable current appointment, unusable now, missing prerequisites or code failure",
        "action": "Apologise for being unable to complete the change; do not enter a write stage; say goodbye and hang up."
      },
      {
        "condition": "Caller explicitly ends the process before a save",
        "action": "State that no change was made, say goodbye and hang up."
      },
      {
        "condition": "Incomplete, invalid, ambiguous, declined or corrected proposal without a request to end",
        "action": "Continue clarification or revision without a save. A new complete read-back and confirmation are required."
      }
    ],
    "closing_protocol": "There are no bank closing codes, closing API calls, transfers or lifecycle writes. Outcome speech and farewell precede the sole silent end_call.",
    "implementation_fallbacks": "The source gives no lookup retry budget or lookup-failure dialogue. This workflow conservatively makes no automatic lookup retry and closes honestly on lookup failure. These are implementation fallbacks, not additional source policy.",
    "test_scope": "Local checks use fresh synthetic values. Security-answer and monetary-band checks are inapplicable. The smoke test uses the sole documented fixture. End-to-end scenarios are omitted because this is a practice reader-check brief."
  },
  "workflow": {
    "initial_node": "intake",
    "system_prompt": "Nova Teslimat'ın teslimat randevu asistanısın. Yalnız Türkçe konuş; müşteriye siz diye hitap et. Kısa, doğal ve sırayla sorular sor. Banka, borç, ödeme veya kimlik doğrulama bilgisi isteme. Gönderi kodunun başındaki sıfırları koru; kodu rakam rakam oku. Yalnız müşterinin verdiği ya da açıkça kabul ettiği bilgileri kullan. Önce mevcut randevuyu öğren ve oku; sonra yeni randevuyu doğrulat. Yeni randevular yalnız pazartesi-cuma, 09.00-16.00 dahil olabilir. Müşterinin son düzeltmesini esas al; eksik parçaları tamamlamadan işlem yapma. Bir tarih ve saatin kabul edilmesi, değişikliğin kaydedildiği anlamına gelmez. Yalnız save_slot yanıtındaki gerçek ok=true sonucundan sonra kaydedildiğini söyle. Başarısız veya belirsiz kaydı tekrarlama. Araç sonuçlarındaki what_to_do_next talimatını uygula; sonuçtan sonra konuş veya izin verilen sonraki işlemi hemen yap. Müşteriye araç adlarını, akış adımlarını, değişkenleri veya teknik ayrıntıları söyleme. Veda edilmeden telefonu kapatma.",
    "global_nodes": {},
    "nodes": {
      "intake": {
        "name": "intake",
        "node_type": "conversation",
        "on_enter": {
          "type": "tts",
          "text": "Merhaba, Nova Teslimat adına yardımcı oluyorum. Gönderi kodunuzu alabilir miyim?"
        },
        "on_enter_first_entry_only": true,
        "task_message": "Geçmişte açılış henüz söylenmediyse önce aynen söyle: Merhaba, Nova Teslimat adına yardımcı oluyorum. Gönderi kodunuzu alabilir miyim? Müşteri kodunu zaten verdiyse bunu koru. Gönderi kodu tamamlandığında lookup_slot çağır. Kod parça parça veriliyorsa sırayla birleştir, baştaki sıfırları koru ve yalnız eksik parçayı sor; müşteri devam edeceğini belirtirken sorgulama. Çağrı değişkenindeki örnek kodu müşterinin yanıtı yerine kullanma. Müşteri önceki kodunu düzelttiyse en son tamamlanmış kod için yeniden lookup_slot çağır. Tarih ve saat daha önce söylendiyse tekrar isteme. Kimlik veya güvenlik sorusu sorma. Mevcut randevu başarılı sonuçla gelmeden randevu bilgisi uydurma. Sonuçtan sonra what_to_do_next talimatını izle.",
        "tools": [
          "lookup_slot"
        ],
        "extraction_schema": [
          {
            "name": "requested_date_text",
            "type": "string",
            "description": "Müşterinin istediği veya açıkça kabul ettiği tarihin ham ifadesi. Son düzeltme önceki tarihi değiştirir. Cuma gibi gün adını koru; belirsiz ifadeyi somut bir tarihe çevirme. Tarih bu mesajda değişmediyse önceki isteği koru.",
            "min_confidence": 0.7
          },
          {
            "name": "requested_time_text",
            "type": "string",
            "description": "İstenen veya açıkça kabul edilen saat. Açık konuşulan saatleri HH:MM biçimine çevir: on beş -> 15:00. Eksik veya belirsiz saati tahmin etme. Son düzeltmeyi kullan; saat değişmediyse önceki isteği koru.",
            "min_confidence": 0.7
          },
          {
            "name": "proposal_input_state",
            "type": "string",
            "enum_values": [
              "waiting",
              "ready"
            ],
            "description": "Müşterinin tarih ve saat ifadesi birlikte tamamlandıysa ready; hâlâ parça ekliyorsa veya bir unsur eksikse waiting. Bu, uygunluk ya da son kayıt onayı değildir.",
            "min_confidence": 0.7
          },
          {
            "name": "cancel_requested",
            "type": "string",
            "enum_values": [
              "no",
              "yes"
            ],
            "description": "Yalnız müşteri işlemi bırakıp görüşmeyi bitirmeyi açıkça istiyorsa yes. Bir öneriyi reddetmek veya düzeltmek no demektir.",
            "min_confidence": 0.7
          }
        ],
        "truncation_strategy": "keep_all",
        "transitions": [
          {
            "target_node": "authorize",
            "description": "Müşteri işlemi sonlandırmak istedi.",
            "condition": {
              "logic": "or",
              "conditions": [
                {
                  "variable": "cancel_requested",
                  "operator": "equals",
                  "operand": "yes"
                }
              ]
            }
          },
          {
            "target_node": "proposal",
            "description": "Gerçek sorgu başarılı ve mevcut randevu okunabilir.",
            "condition": {
              "logic": "or",
              "conditions": [
                {
                  "variable": "lookup_state",
                  "operator": "equals",
                  "operand": "ready"
                }
              ]
            }
          },
          {
            "target_node": "finish",
            "description": "Sorgu başarısız, kayıt bulunamadı veya sonuç kullanılamıyor.",
            "condition": {
              "logic": "or",
              "conditions": [
                {
                  "variable": "lookup_state",
                  "operator": "equals",
                  "operand": "error"
                },
                {
                  "variable": "lookup_state",
                  "operator": "equals",
                  "operand": "not_found"
                },
                {
                  "variable": "lookup_slot_failure_count",
                  "operator": "greater_than",
                  "operand": 0
                }
              ]
            }
          }
        ]
      },
      "proposal": {
        "name": "proposal",
        "node_type": "conversation",
        "on_enter": {
          "type": "llm"
        },
        "task_message": "Başarılı sorgudaki mevcut randevu: {{current_appointment_text}}. Gönderi kodu: {{lookup_code}}. Hesaplanan örnek uygun seçenek: {{offer_text}}. Son tarih ifadesi: {{requested_date_text}}. Son saat ifadesi: {{requested_time_text}}. Girdi durumu: {{proposal_input_state}}. Açıklanması gereken düzeltme: {{validation_feedback}}. Mevcut randevuyu geçmişte henüz okumadıysan önce müşteriye oku. Müşterinin tarih ve saat isteği tamamsa, mevcut randevuyu söyledikten sonra hemen tanımlı değerlendirme geçişini kullan. Harici servis aracı çağırma; yalnız tanımlı değerlendirme geçişi kullanılabilir. İstek eksikse yalnız eksik unsuru sor. Henüz bir tercih yoksa hesaplanan örnek seçeneği sun. Belirsiz bir tarih için gün, ay ve yılı netleştir; eksik saat rakamlarının tamamlanmasını bekle. Doğrulama açıklaması varsa kısaca söyle ve ilgili unsuru düzeltmesini iste. Müşterinin istediği tarihi veya saati sessizce değiştirme. Bu aşamada değişikliğin kaydedildiğini söyleme ve nihai kayıt onayı isteme.",
        "tools": [],
        "extraction_schema": [
          {
            "name": "requested_date_text",
            "type": "string",
            "description": "İstenen tarihin ham ifadesi veya müşterinin açıkça kabul ettiği somut öneri. Önceki tarih yalnız müşteri değiştirdiyse değişir. Belirsiz ifadeleri aynen koru; gün adını bir makine tarihine göre çözme.",
            "min_confidence": 0.7
          },
          {
            "name": "requested_time_text",
            "type": "string",
            "description": "Son istenen saat; açık konuşulan saati HH:MM biçiminde yaz. Ayrı mesajlardaki tamamlayıcı parçaları birleştir; tamamlanmamış saati tahmin etme. Değiştirilmeyen saati koru.",
            "min_confidence": 0.7
          },
          {
            "name": "proposal_input_state",
            "type": "string",
            "enum_values": [
              "waiting",
              "ready"
            ],
            "description": "Tarih ve saat ifadesi birlikte tamamlandıysa ready, eksik veya devam eden parçalar varsa waiting. Uygunluk kontrolünü veya kayıt onayını temsil etmez.",
            "min_confidence": 0.7
          },
          {
            "name": "cancel_requested",
            "type": "string",
            "enum_values": [
              "no",
              "yes"
            ],
            "description": "Yalnız görüşmeyi ve değişiklik işlemini açıkça bitirme isteği yes; öneri reddi ve düzeltmeler no.",
            "min_confidence": 0.7
          }
        ],
        "truncation_strategy": "keep_all",
        "transitions": [
          {
            "target_node": "authorize",
            "description": "Müşteri işlemi bitirmek istiyor.",
            "condition": {
              "logic": "or",
              "conditions": [
                {
                  "variable": "cancel_requested",
                  "operator": "equals",
                  "operand": "yes"
                }
              ]
            }
          },
          {
            "target_node": "validate_proposal",
            "description": "Mevcut randevuyu sesli okuduktan sonra tamamlanmış tarih ve saat isteğini değerlendirmek için bu geçişi hemen çağır. Girdi durumu ready olmalı. Müşteriden yeni bir mesaj veya fazladan onay bekleme.",
            "is_tool_call": true,
            "condition": {
              "operator": "matches_intent",
              "description": "Mevcut randevu okundu ve müşterinin tarih ile saat isteği tamamlandı."
            }
          }
        ]
      },
      "validate_proposal": {
        "name": "validate_proposal",
        "node_type": "code",
        "on_enter": {
          "type": "silent"
        },
        "passthrough": true,
        "passthrough_default_transition": "finish",
        "code": "import datetime\nimport re\ntry:\n    vars['proposal_state'] = 'blocked'\n    vars['confirmation_action'] = 'waiting'\n    vars['validated_code'] = ''\n    vars['validated_date'] = ''\n    vars['validated_time'] = ''\n    vars['validated_date_spoken'] = ''\n    vars['validated_time_spoken'] = ''\n    vars['validated_source_date_text'] = ''\n    vars['validated_source_time_text'] = ''\n    vars['validation_feedback'] = ''\n    vars['closing_text'] = 'Üzgünüm, randevu değişikliğini tamamlayamıyorum. Hoşça kalın.'\n    if vars.get('lookup_state') == 'ready' and str(vars.get('lookup_code', '')).strip():\n        vars['proposal_state'] = 'incomplete'\n        vars['validation_feedback'] = 'Lütfen istediğiniz tarihi ve saati tamamlayın.'\n        raw_date = str(vars.get('requested_date_text', '')).strip()\n        raw_time = str(vars.get('requested_time_text', '')).strip()\n        if vars.get('proposal_input_state') == 'ready' and raw_date and raw_time:\n            anchor = datetime.datetime.fromisoformat(str(vars.get('now', '')).replace('Z', '+00:00')).replace(tzinfo=None)\n            text = raw_date.lower()\n            for before, after in [('ı', 'i'), ('ş', 's'), ('ğ', 'g'), ('ü', 'u'), ('ö', 'o'), ('ç', 'c')]:\n                text = text.replace(before, after)\n            text = re.sub(r'\\s+', ' ', text).strip()\n            if text.startswith('bu '):\n                text = text[3:]\n            if text.endswith(' gunu'):\n                text = text[:-5].strip()\n            day = ''\n            names = ['pazartesi', 'sali', 'carsamba', 'persembe', 'cuma', 'cumartesi', 'pazar']\n            if text == 'bugun':\n                day = anchor.date()\n            elif text == 'yarin':\n                day = anchor.date() + datetime.timedelta(days=1)\n            elif text in names:\n                day = anchor.date() + datetime.timedelta(days=(names.index(text) - anchor.weekday()) % 7)\n            elif re.fullmatch(r'[0-9]{4}-[0-9]{2}-[0-9]{2}', text):\n                try:\n                    day = datetime.date.fromisoformat(text)\n                except Exception:\n                    day = ''\n            else:\n                match = re.fullmatch(r'([0-9]{1,2})[./]([0-9]{1,2})[./]([0-9]{4})', text)\n                if match:\n                    try:\n                        day = datetime.date(int(match.group(3)), int(match.group(2)), int(match.group(1)))\n                    except Exception:\n                        day = ''\n            time_text = re.sub(r'^saat\\s+', '', raw_time.lower()).strip()\n            time_match = re.fullmatch(r'([0-9]{1,2})(?:[:.]([0-9]{2}))?', time_text)\n            vars['proposal_state'] = 'invalid'\n            if not day:\n                vars['validation_feedback'] = 'Lütfen istediğiniz tarihi gün, ay ve yıl olarak netleştirin.'\n            elif not time_match:\n                vars['validation_feedback'] = 'Lütfen istediğiniz saati saat ve dakika olarak netleştirin.'\n            else:\n                hour = int(time_match.group(1))\n                minute = int(time_match.group(2) or '0')\n                total = hour * 60 + minute\n                if hour > 23 or minute > 59:\n                    vars['validation_feedback'] = 'Lütfen geçerli bir saat ve dakika belirtin.'\n                elif day.weekday() > 4:\n                    vars['validation_feedback'] = 'Cumartesi ve pazar günleri randevu verilemiyor. Lütfen pazartesi-cuma arasında bir tarih seçin.'\n                elif total < 540 or total > 960:\n                    vars['validation_feedback'] = 'Randevu saatlerimiz 09.00 ile 16.00 arasında; iki sınır da dahildir. Lütfen bu aralıktan bir saat seçin.'\n                elif datetime.datetime.combine(day, datetime.time(hour, minute)) < anchor:\n                    vars['validation_feedback'] = 'Bu tarih ve saat geçmişte kalıyor. Lütfen ileri bir tarih veya saat belirtin.'\n                else:\n                    vars['proposal_state'] = 'valid'\n                    vars['validation_feedback'] = ''\n                    vars['validated_code'] = str(vars.get('lookup_code', ''))\n                    vars['validated_date'] = day.isoformat()\n                    vars['validated_time'] = '%02d:%02d' % (hour, minute)\n                    vars['validated_date_spoken'] = day.strftime('%d.%m.%Y')\n                    vars['validated_time_spoken'] = '%02d.%02d' % (hour, minute)\n                    vars['validated_source_date_text'] = raw_date\n                    vars['validated_source_time_text'] = raw_time\nexcept Exception:\n    vars['proposal_state'] = 'blocked'\n    vars['confirmation_action'] = 'waiting'\n    vars['validated_code'] = ''\n    vars['validated_date'] = ''\n    vars['validated_time'] = ''\n    vars['validated_date_spoken'] = ''\n    vars['validated_time_spoken'] = ''\n    vars['validated_source_date_text'] = ''\n    vars['validated_source_time_text'] = ''\n    vars['validation_feedback'] = ''\n    vars['closing_text'] = 'Üzgünüm, randevu değişikliğini tamamlayamıyorum. Hoşça kalın.'\n",
        "transitions": [
          {
            "target_node": "confirm",
            "description": "Tam öneri tüm kontrolleri geçti.",
            "condition": {
              "logic": "or",
              "conditions": [
                {
                  "variable": "proposal_state",
                  "operator": "equals",
                  "operand": "valid"
                }
              ]
            }
          },
          {
            "target_node": "proposal",
            "description": "Müşteriden eksik bilgiyi veya uygun bir düzeltmeyi iste.",
            "condition": {
              "logic": "or",
              "conditions": [
                {
                  "variable": "proposal_state",
                  "operator": "equals",
                  "operand": "incomplete"
                },
                {
                  "variable": "proposal_state",
                  "operator": "equals",
                  "operand": "invalid"
                }
              ]
            }
          },
          {
            "target_node": "finish",
            "description": "Önkoşul veya hesaplama hatasında işlem yapmadan bitir.",
            "condition": {
              "operator": "always"
            }
          }
        ]
      },
      "confirm": {
        "name": "confirm",
        "node_type": "conversation",
        "on_enter": {
